import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  DeleteObjectCommand,
  GetObjectCommand,
  PutObjectCommand,
  S3Client,
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { randomUUID } from 'crypto';
import { DetectedFileType, FILE_EXTENSIONS } from '../files/file-signature';

export type StoragePrefix = 'avatars' | 'logos' | 'cvs';

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';

/** Only keys generated by this service are ever deleted or presigned. */
const KEY_PATTERNS: Record<StoragePrefix, RegExp> = {
  avatars: new RegExp(`^avatars/${UUID}\\.(jpeg|jpg|png|webp)$`),
  logos: new RegExp(`^logos/${UUID}\\.(jpeg|jpg|png|webp)$`),
  cvs: new RegExp(`^cvs/${UUID}\\.pdf$`),
};

/** Presigned download URLs are valid for 15 minutes. */
export const PRESIGNED_URL_TTL_SECONDS = 900;

/**
 * Thin wrapper around S3. Centralises key generation and — most importantly —
 * validates every key before a delete/presign, so a key coming from the
 * database can never target another prefix or an arbitrary object.
 */
@Injectable()
export class StorageService {
  private readonly logger = new Logger(StorageService.name);
  private readonly s3: S3Client;
  private readonly bucket: string;
  private readonly region: string;

  constructor(config: ConfigService) {
    this.region = config.get<string>('aws.region')!;
    this.bucket = config.get<string>('aws.bucketName')!;
    this.s3 = new S3Client({
      region: this.region,
      credentials: {
        accessKeyId: config.get<string>('aws.accessKeyId')!,
        secretAccessKey: config.get<string>('aws.secretAccessKey')!,
      },
    });
  }

  isValidKey(key: string | null | undefined, prefix: StoragePrefix): boolean {
    return typeof key === 'string' && KEY_PATTERNS[prefix].test(key);
  }

  /** Uploads a buffer under a server-generated key and returns that key. */
  async upload(
    prefix: StoragePrefix,
    body: Buffer,
    contentType: DetectedFileType,
  ): Promise<string> {
    const key = `${prefix}/${randomUUID()}.${FILE_EXTENSIONS[contentType]}`;
    await this.s3.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: body,
        ContentType: contentType,
      }),
    );
    return key;
  }

  publicUrl(key: string): string {
    return `https://${this.bucket}.s3.${this.region}.amazonaws.com/${key}`;
  }

  /** Extracts the key from one of OUR public URLs, or null if it is not one. */
  keyFromPublicUrl(url: string, prefix: StoragePrefix): string | null {
    try {
      const parsed = new URL(url);
      const expectedHost = `${this.bucket}.s3.${this.region}.amazonaws.com`;
      if (parsed.protocol !== 'https:' || parsed.host !== expectedHost) {
        return null;
      }
      const key = decodeURIComponent(parsed.pathname.slice(1));
      return this.isValidKey(key, prefix) ? key : null;
    } catch {
      return null;
    }
  }

  /** Deletes an object; refuses (and logs) any key we did not generate. */
  async delete(key: string, prefix: StoragePrefix): Promise<void> {
    if (!this.isValidKey(key, prefix)) {
      this.logger.warn(`Refused to delete an unexpected ${prefix} key`);
      return;
    }
    await this.s3.send(
      new DeleteObjectCommand({ Bucket: this.bucket, Key: key }),
    );
  }

  async deleteByPublicUrl(url: string, prefix: StoragePrefix): Promise<void> {
    const key = this.keyFromPublicUrl(url, prefix);
    if (!key) {
      this.logger.warn(`Refused to delete an unexpected ${prefix} URL`);
      return;
    }
    await this.delete(key, prefix);
  }

  /** Same as delete(), but never throws (used to clean up replaced files). */
  async deleteQuietly(
    target: { key?: string | null; url?: string | null },
    prefix: StoragePrefix,
  ): Promise<void> {
    try {
      if (target.key) await this.delete(target.key, prefix);
      else if (target.url) await this.deleteByPublicUrl(target.url, prefix);
    } catch {
      this.logger.error(`Failed to delete a replaced ${prefix} object`);
    }
  }

  /** Short-lived download URL for a private object (CVs). */
  async presignDownload(
    key: string,
    prefix: StoragePrefix,
    expiresIn = PRESIGNED_URL_TTL_SECONDS,
  ): Promise<string> {
    if (!this.isValidKey(key, prefix)) {
      throw new NotFoundException('File not found.');
    }
    return getSignedUrl(
      this.s3,
      new GetObjectCommand({ Bucket: this.bucket, Key: key }),
      { expiresIn },
    );
  }
}
